1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {OutgoingMessage} from '../../types/messages.js';
6	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
7	import {validateMessage} from './validation.js';
8	import type {ValidationResult} from './validation.js';
9	import {PerSessionLock} from '../../shared/perSessionLock.js';
10	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
11	import {AIError} from '../../types/ai.js';
12	import type {MessageChunk} from '../../types/ai.js';
13	import {
14	  createUserEntry,
15	  createAssistantEntry,
16	  createThinkingEntry,
17	  createToolEntry,
18	} from '../../orchestration/entryFactories.js';
19	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
20	import {sendJson, sendUpsert, sendDelta, sendCommit, sendSkip, sendError, sendStreamEnd} from './sender.js';
21	import {log} from '../../shared/logger.js';
22	
23	interface StreamState {
24	  thinkingIndex: number | null;
25	  assistantIndex: number | null;
26	  suppressOutput: boolean;
27	  sentAssistantIndices: number[];
28	}
29	
30	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
31	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
32	export function createMessageHandler(orchestrator: ChatOrchestrator) {
33	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
34	  const lock = new PerSessionLock();
35	  return function handleMessage(
36	    ws: WebSocket,
37	    session: ChatSession,
38	    rawMessage: unknown,
39	    signal?: AbortSignal
40	  ): Promise<void> {
41	    const validation = validateMessage(rawMessage);
42	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
43	    if (isUserMessageFrame(rawMessage)) {
44	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
45	    }
46	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
47	    return wsErrorHandler(ws, async () => answerFrame(ws, validation));
48	  };
49	}
50	
51	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
52	async function answerInTurn(
53	  ws: WebSocket,
54	  session: ChatSession,
55	  orchestrator: ChatOrchestrator,
56	  validation: ValidationResult,
57	  signal: AbortSignal | undefined
58	): Promise<void> {
59	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
60	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
61	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
62	    return;
63	  }
64	  const startedAt = Date.now();
65	  try {
66	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
67	  } finally {
68	    endTurn(ws, session, signal, startedAt);
69	  }
70	}
71	
72	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
73	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
74	  if (signal?.aborted) {
75	    log.info('message', 'turn abandoned: its socket closed', {
76	      sessionId: session.sessionId,
77	      elapsedMs: Date.now() - startedAt,
78	    });
79	    return;
80	  }
81	  sendStreamEnd(ws);
82	}
83	
84	async function answerUserMessage(
85	  ws: WebSocket,
86	  session: ChatSession,
87	  orchestrator: ChatOrchestrator,
88	  validation: ValidationResult,
89	  signal: AbortSignal | undefined
90	): Promise<void> {
91	  const message = validation.valid ? validation.data : undefined;
92	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
93	  answerFrame(ws, validation);
94	}
95	
96	function answerFrame(ws: WebSocket, validation: ValidationResult): void {
97	  if (!validation.valid) {
98	    log.warn('message', 'validation failed', {error: validation.error});
99	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
100	    return;
101	  }
102	
103	  const message = validation.data;
104	  if (message.type === 'ping') handlePing(ws, message.timestamp);
105	}
106	
107	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
108	function isUserMessageFrame(rawMessage: unknown): boolean {
109	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
110	}
111	
112	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
113	  try {
114	    await action();
115	  } catch (error) {
116	    const message = error instanceof Error ? error.message : 'Unknown error';
117	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
118	    log.error('message', 'handling error', {error: message, code});
119	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
120	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
121	      return;
122	    }
123	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
124	  }
125	}
126	
127	async function handleUserMessage(
128	  ws: WebSocket,
129	  session: ChatSession,
130	  orchestrator: ChatOrchestrator,
131	  content: string,
132	  signal: AbortSignal | undefined
133	): Promise<void> {
134	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
135	
136	  const userEntry = createUserEntry(content);
137	  const userIndex = appendEntry(session, userEntry);
138	  sendUpsert(ws, userIndex, userEntry);
139	
140	  const parser = new ThinkingTagParser();
141	  const state: StreamState = {
142	    thinkingIndex: null,
143	    assistantIndex: null,
144	    suppressOutput: false,
145	    sentAssistantIndices: [],
146	  };
147	
148	  let textChunkCount = 0;
149	
150	  try {
151	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
152	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
153	      if (signal?.aborted) break;
154	      textChunkCount = logChunk(chunk, textChunkCount);
155	      processChunk(ws, session, state, parser, chunk);
156	    }
157	  } finally {
158	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
159	    flushHeldText(ws, session, state, parser);
160	    closeCutOff(ws, session, state, 'thinkingIndex');
161	    closeCutOff(ws, session, state, 'assistantIndex');
162	  }
163	
164	  if (textChunkCount > 0) {
165	    log.debug('stream', `received ${textChunkCount} text chunks`);
166	  }
167	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
168	}
169	
170	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
171	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
172	  if (chunk.type === 'text') return textChunkCount + 1;
173	
174	  if (textChunkCount > 0) {
175	    log.debug('stream', `received ${textChunkCount} text chunks`);
176	  }
177	
178	  if (chunk.type === 'tool_result') {
179	    log.debug('stream', 'tool_result chunk', {
180	      messageCount: chunk.clientMessages.length,
181	      types: chunk.clientMessages.map(m => m.type),
182	    });
183	    return 0;
184	  }
185	
186	  log.debug('stream', 'chunk', {type: chunk.type});
187	  return 0;
188	}
189	
190	function processChunk(
191	  ws: WebSocket,
192	  session: ChatSession,
193	  state: StreamState,
194	  parser: ThinkingTagParser,
195	  chunk: MessageChunk
196	): void {
197	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
198	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
199	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
200	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
201	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
202	}
203	
204	function processTextChunk(
205	  ws: WebSocket,
206	  session: ChatSession,
207	  state: StreamState,
208	  parser: ThinkingTagParser,
209	  text: string
210	): void {
211	  const segments = parser.push(text);
212	  for (const segment of segments) {
213	    handleTextSegment(ws, session, state, segment);
214	  }
215	}
216	
217	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
218	  if (segment.type === 'thinking') {
219	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
220	    return;
221	  }
222	  commitAndClear(ws, session, state, 'thinkingIndex');
223	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
224	}
225	
226	function streamSegment(
227	  ws: WebSocket,
228	  session: ChatSession,
229	  state: StreamState,
230	  key: StateIndexKey,
231	  createEntry: EntryFactory,
232	  content: string
233	): void {
234	  const isNew = initSegment(session, state, key, createEntry);
235	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
236	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
237	  appendDelta(session, state[key]!, content);
238	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
239	}
240	
241	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
242	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
243	  markSuppressed(session, index);
244	  sendSkip(ws, index);
245	}
246	
247	function markSuppressed(session: ChatSession, index: number): void {
248	  const entry = session.entries[index];
249	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
250	}
251	
252	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
253	  if (state[key] !== null) return false;
254	  state[key] = appendEntry(session, createEntry());
255	  return true;
256	}
257	
258	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
259	  const index = state[key];
260	  if (index === null) return;
261	
262	  commitEntry(session, index);
263	  state[key] = null;
264	
265	  // Only what the client received can be retracted, and only assistant entries.
266	  if (state.suppressOutput) return;
267	
268	  sendCommit(ws, index);
269	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
270	}
271	
272	function processToolUseChunk(
273	  ws: WebSocket,
274	  session: ChatSession,
275	  toolCall: {name: string; input: Record<string, unknown>}
276	): void {
277	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
278	  const toolIndex = appendEntry(session, toolEntry);
279	  sendUpsert(ws, toolIndex, toolEntry);
280	}
281	
282	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
283	  for (const msg of clientMessages) {
284	    log.debug('stream', 'forwarding client message to frontend', {
285	      type: msg.type,
286	      index: 'index' in msg ? msg.index : undefined,
287	    });
288	    sendJson(ws, msg);
289	  }
290	}
291	
292	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
293	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
294	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
295	  commitOpenEntries(ws, session, state);
296	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
297	
298	  for (const idx of state.sentAssistantIndices) {
299	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
300	    markSuppressed(session, idx);
301	  }
302	
303	  state.sentAssistantIndices = [];
304	  state.suppressOutput = true;
305	}
306	
307	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
308	  flushHeldText(ws, session, state, parser);
309	  commitOpenEntries(ws, session, state);
310	}
311	
312	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
313	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
314	  for (const segment of parser.flush()) {
315	    handleTextSegment(ws, session, state, segment);
316	  }
317	}
318	
319	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
320	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
321	  const index = state[key];
322	  if (index === null) return;
323	  markTruncated(session, index);
324	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
325	  commitAndClear(ws, session, state, key);
326	}
327	
328	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
329	  commitAndClear(ws, session, state, 'thinkingIndex');
330	  commitAndClear(ws, session, state, 'assistantIndex');
331	}
332	
333	function handlePing(ws: WebSocket, timestamp: number): void {
334	  ws.send(JSON.stringify({type: 'pong', timestamp}));
335	}
336

